import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Filtern, Sortieren, Gruppieren","description":"Einträge in einer Ansicht filtern, sortieren und gruppieren — inklusive Filtergruppen und Aggregaten.","frontmatter":{"title":"Filtern, Sortieren, Gruppieren","description":"Einträge in einer Ansicht filtern, sortieren und gruppieren — inklusive Filtergruppen und Aggregaten."},"headers":[],"relativePath":"ansichten/filtern-sortieren-gruppieren.md","filePath":"ansichten/filtern-sortieren-gruppieren.md","lastUpdated":1786174778000}'),l={name:"ansichten/filtern-sortieren-gruppieren.md"};function a(s,e,d,o,g,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="filtern-sortieren-gruppieren" tabindex="-1">Filtern, Sortieren, Gruppieren <a class="header-anchor" href="#filtern-sortieren-gruppieren" aria-label="Permalink to &quot;Filtern, Sortieren, Gruppieren&quot;">​</a></h1><p>Diese drei Werkzeuge bestimmen, welche Einträge einer Ansicht zu sehen sind und wie sie angeordnet werden. Alle drei gelten <strong>nur für die aktuelle Ansicht</strong> — andere Ansichten desselben Grids bleiben unberührt.</p><h2 id="filtern" tabindex="-1">Filtern <a class="header-anchor" href="#filtern" aria-label="Permalink to &quot;Filtern&quot;">​</a></h2><p>Ein Filter legt fest, welche Einträge sichtbar sind. Die Oberfläche formuliert das als <em>In dieser Ansicht zeige Einträge …</em>.</p><h3 id="einen-filter-anlegen" tabindex="-1">Einen Filter anlegen <a class="header-anchor" href="#einen-filter-anlegen" aria-label="Permalink to &quot;Einen Filter anlegen&quot;">​</a></h3><ol><li>Klicken Sie in der Werkzeugleiste auf <strong>Filter</strong>.</li><li>Wählen Sie <strong>Filter hinzufügen</strong>.</li><li>Wählen Sie <strong>Feld</strong>, <strong>Bedingung</strong> und <strong>Wert</strong>.</li></ol><p>Beispiel: <code>Status</code> <code>entspricht</code> <code>Offen</code>.</p><h3 id="verfugbare-bedingungen" tabindex="-1">Verfügbare Bedingungen <a class="header-anchor" href="#verfugbare-bedingungen" aria-label="Permalink to &quot;Verfügbare Bedingungen&quot;">​</a></h3><p>Welche Bedingungen zur Auswahl stehen, hängt vom Spaltentyp ab:</p><table tabindex="0"><thead><tr><th>Bedingung</th><th>Verfügbar bei</th></tr></thead><tbody><tr><td>entspricht / entspricht nicht</td><td>den meisten Typen</td></tr><tr><td>enthält / enthält nicht</td><td>textartigen Typen</td></tr><tr><td>ist kleiner als / ist größer als</td><td>Zahl, Kommazahl, Währung</td></tr><tr><td>ist vor / ist nach</td><td>Datum, Datum und Uhrzeit</td></tr><tr><td>enthält eines von / keines von / alle von</td><td>Mehrfachauswahl, Mehrfach-Verknüpfung</td></tr><tr><td>ist / ist nicht</td><td>Benutzer, Erstellt von</td></tr><tr><td>ist leer / ist nicht leer</td><td>fast allen Typen</td></tr></tbody></table><p>Die vollständige Zuordnung steht unter <a href="/docs/referenz/filterbedingungen">Filterbedingungen</a>.</p><h3 id="relative-werte" tabindex="-1">Relative Werte <a class="header-anchor" href="#relative-werte" aria-label="Permalink to &quot;Relative Werte&quot;">​</a></h3><p>Bei Datumsfeldern können Sie statt eines festen Datums einen relativen Ausdruck wählen:</p><ul><li><strong>heute</strong>, <strong>morgen</strong>, <strong>gestern</strong></li><li><strong>vor X Tagen</strong>, <strong>in X Tagen</strong></li><li><strong>exaktes Datum</strong></li></ul><p>Bei personenbezogenen Feldern steht <strong>angemeldeter Benutzer</strong> zur Verfügung.</p><div class="tip custom-block"><p class="custom-block-title">Persönliche Ansichten ohne Kopien</p><p>Die Kombination aus <code>Zuständig</code> <code>ist</code> <code>angemeldeter Benutzer</code> erzeugt eine Ansicht, die für jede Person automatisch ihre eigenen Einträge zeigt. Sie brauchen also keine Ansicht pro Teammitglied.</p></div><h3 id="filtergruppen" tabindex="-1">Filtergruppen <a class="header-anchor" href="#filtergruppen" aria-label="Permalink to &quot;Filtergruppen&quot;">​</a></h3><p>Mehrere Bedingungen verknüpfen Sie über <strong>Filtergruppe hinzufügen</strong> mit <strong>und</strong> beziehungsweise <strong>oder</strong>:</p><ul><li><strong>und</strong> — <em>Alle der folgenden Bedingungen treffen zu</em></li><li><strong>oder</strong> — <em>Eine der folgenden Bedingungen trifft zu</em></li></ul><p>Gruppen lassen sich verschachteln, um Ausdrücke wie „A und (B oder C)&quot; abzubilden.</p><div class="warning custom-block"><p class="custom-block-title">Höchstens drei Verschachtelungsebenen</p><p>ApptiveGrid erlaubt maximal drei Ebenen und meldet sonst <em>Filterbedingungen können nur 3 Ebenen tief verschachtelt werden</em>.</p><p>Brauchen Sie mehr, ist meist ein Hilfsfeld die bessere Lösung: Legen Sie ein Feld vom Typ <strong>Formel</strong> oder <strong>Häkchen</strong> an, das die komplexe Bedingung abbildet, und filtern Sie darauf.</p></div><h3 id="unvollstandige-filter" tabindex="-1">Unvollständige Filter <a class="header-anchor" href="#unvollstandige-filter" aria-label="Permalink to &quot;Unvollständige Filter&quot;">​</a></h3><p>Solange eine Bedingung unvollständig ist, meldet ApptiveGrid <em>Alle vorhandenen Filter müssen gültig sein</em> und wendet den Filter nicht an. Vervollständigen oder entfernen Sie die Bedingung.</p><h3 id="gespeicherter-und-temporarer-filter" tabindex="-1">Gespeicherter und temporärer Filter <a class="header-anchor" href="#gespeicherter-und-temporarer-filter" aria-label="Permalink to &quot;Gespeicherter und temporärer Filter&quot;">​</a></h3><p>Es gibt zwei Arten:</p><table tabindex="0"><thead><tr><th>Art</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Gespeicherter Filter</strong></td><td>Teil der Ansicht. Gilt für alle, die diese Ansicht sehen — auch für geteilte Links.</td></tr><tr><td><strong>Temporärer Filter</strong></td><td>Nur für Sie und nur in dieser Sitzung. Die Oberfläche nennt das <em>Einträge suchen und filtern (temporär)</em>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Erst temporär probieren</p><p>Wenn Sie in einer Ansicht arbeiten, die auch Kollegen nutzen, verwenden Sie den temporären Filter. Ein gespeicherter Filter ändert die Ansicht für alle.</p></div><h3 id="„zeile-gefiltert" tabindex="-1">„Zeile gefiltert&quot; <a class="header-anchor" href="#„zeile-gefiltert" aria-label="Permalink to &quot;„Zeile gefiltert&quot;&quot;">​</a></h3><p>Bearbeiten Sie einen Eintrag so, dass er nicht mehr zum Filter passt, meldet ApptiveGrid <strong>Zeile gefiltert</strong> und blendet ihn aus. Der Eintrag ist nicht gelöscht — er erfüllt nur die Filterbedingung nicht mehr und ist in einer ungefilterten Ansicht weiterhin vorhanden.</p><h2 id="sortieren" tabindex="-1">Sortieren <a class="header-anchor" href="#sortieren" aria-label="Permalink to &quot;Sortieren&quot;">​</a></h2><p>Die Sortierung legt die Reihenfolge der Einträge fest.</p><ol><li>Klicken Sie auf <strong>Sortieren</strong>.</li><li>Wählen Sie ein Feld und die Richtung.</li><li>Fügen Sie bei Bedarf weitere Felder hinzu — sie greifen bei Gleichstand.</li></ol><p>Beispiel: zuerst nach <code>Priorität</code> absteigend, dann nach <code>Fällig am</code> aufsteigend.</p><h2 id="gruppieren" tabindex="-1">Gruppieren <a class="header-anchor" href="#gruppieren" aria-label="Permalink to &quot;Gruppieren&quot;">​</a></h2><p>Die Gruppierung bündelt Einträge nach den Werten eines Feldes. Jede Gruppe erhält eine Kopfzeile und lässt sich ein- und ausklappen.</p><p>Besonders geeignet sind Felder vom Typ <strong>Einzelauswahl</strong>, <strong>Häkchen</strong>, <strong>Benutzer</strong> und <strong>Eintrag verknüpfen</strong>.</p><h3 id="aggregate" tabindex="-1">Aggregate <a class="header-anchor" href="#aggregate" aria-label="Permalink to &quot;Aggregate&quot;">​</a></h3><p>Je Gruppe können Sie einen Kennwert einblenden:</p><table tabindex="0"><thead><tr><th>Aggregat</th><th>Bedeutung</th><th>Sinnvoll bei</th></tr></thead><tbody><tr><td><strong>Summe</strong></td><td>Summe aller Werte</td><td>Zahl, Kommazahl, Währung</td></tr><tr><td><strong>Durchschnitt</strong></td><td>Mittelwert</td><td>Zahl, Kommazahl, Währung</td></tr><tr><td><strong>Minimum</strong></td><td>kleinster Wert</td><td>numerische Typen, Datum</td></tr><tr><td><strong>Maximum</strong></td><td>größter Wert</td><td>numerische Typen, Datum</td></tr><tr><td><strong>Gefüllt</strong></td><td>Anzahl der Einträge mit Wert</td><td>allen Typen</td></tr><tr><td><strong>Leer</strong></td><td>Anzahl der Einträge ohne Wert</td><td>allen Typen</td></tr><tr><td><strong>Angehakt</strong></td><td>Anzahl der gesetzten Häkchen</td><td>Häkchen</td></tr><tr><td><strong>Nicht angehakt</strong></td><td>Anzahl der nicht gesetzten Häkchen</td><td>Häkchen</td></tr><tr><td><strong>Keines</strong></td><td>kein Kennwert</td><td>–</td></tr></tbody></table><p>Das Aggregat wählen Sie <strong>direkt in der Fußzeile einer Gruppe</strong>: Ein Klick auf den Wert unter einer Spalte öffnet die Auswahl, das aktive Aggregat ist mit einem Häkchen markiert.</p><div class="tip custom-block"><p class="custom-block-title">Je Spalte ein eigenes Aggregat</p><p>Die Einstellung gilt je Spalte, nicht für die ganze Gruppe. In einer nach Kunde gruppierten Ansicht können Sie also gleichzeitig die <strong>Summe</strong> der Beträge, den <strong>Durchschnitt</strong> der Laufzeiten und die <strong>Anzahl</strong> der ausgefüllten Notizfelder anzeigen.</p></div><div class="tip custom-block"><p class="custom-block-title">Auswertung ohne Diagramm</p><p>Gruppierung mit Summe ist der schnellste Weg zu einer Auswertung: „Umsatz je Kunde&quot; ist eine Gruppierung nach Kunde mit der Summe des Betragsfeldes — kein zusätzliches Werkzeug nötig.</p></div><h2 id="summenzeile" tabindex="-1">Summenzeile <a class="header-anchor" href="#summenzeile" aria-label="Permalink to &quot;Summenzeile&quot;">​</a></h2><p>Unter numerischen Spalten lässt sich eine <strong>Summe</strong> über alle sichtbaren Einträge einblenden. Sie berücksichtigt den aktiven Filter.</p><p>Verfügbar bei <strong>Zahl</strong>, <strong>Kommazahl</strong> und <strong>Währung</strong>.</p><h2 id="zusammenspiel" tabindex="-1">Zusammenspiel <a class="header-anchor" href="#zusammenspiel" aria-label="Permalink to &quot;Zusammenspiel&quot;">​</a></h2><p>Die drei Werkzeuge wirken in dieser Reihenfolge:</p><ol><li><strong>Filter</strong> entscheidet, welche Einträge überhaupt dabei sind.</li><li><strong>Gruppierung</strong> bündelt die verbleibenden Einträge.</li><li><strong>Sortierung</strong> ordnet innerhalb der Gruppen.</li></ol><p>Summen und Aggregate beziehen sich immer auf die <strong>gefilterte</strong> Menge.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/grids/suche">Suche</a> — der Unterschied zwischen Suchen und Filtern</li><li><a href="/docs/ansichten/spalten-verwalten">Spalten verwalten</a></li><li><a href="/docs/referenz/filterbedingungen">Filterbedingungen</a></li><li><a href="/docs/ansichten/ansicht-teilen">Ansicht teilen</a></li></ul>',51)])])}const c=t(l,[["render",a]]);export{p as __pageData,c as default};
